insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The author suggests that frequent practice is effective only when learners receive feedback on their mistakes during periods of change, as described in a research summary in a central student forum context.','The author believes practice works best if learners are told what they did wrong.','The author suggests that practice and feedback are unrelated.','The author claims feedback is useful only when students stop practicing.','The author believes mistakes should be ignored during practice.','A','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_39", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The new system was adopted not because it was cheaper, but because it made the process more transparent in small communities, as described in a public debate in a online student forum context.','The new system was rejected because it was not transparent.','The main reason for adopting the new system was improved transparency rather than lower cost.','The process became less transparent after the new system was adopted.','The new system was adopted mainly because it reduced costs.','B','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_39", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'Even though the experiment was small, its results raised important questions for future research when resources are limited, as described in a training program in a evening student forum context.','The results were ignored because the experiment was not small.','Future research became unnecessary after the experiment.','Despite its limited size, the experiment produced results that future studies should examine.','The experiment was too large to raise useful questions.','C','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_39", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The passage implies that convenience may encourage people to use a service, but it does not guarantee satisfaction under careful supervision, as described in an evaluation report in a summer student forum context.','The passage argues that inconvenient services attract the most users.','The passage denies that convenience affects service use.','The passage says convenience always guarantees satisfaction.','The passage suggests that a convenient service can attract users without necessarily satisfying them.','D','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_39", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',7,'The committee approved the plan only after several risks had been identified and addressed after initial trials, as described in a committee meeting in a advanced student forum context.','The plan was accepted once the committee had dealt with the risks it found.','The committee rejected the plan because all risks were addressed.','The plan was accepted although no risks were identified.','The committee approved the plan before considering any risks.','A','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_39", "restatement", "practice_pool"]'::jsonb,70,'C1','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The decline in complaints was gradual, so managers were careful not to attribute it to a single change in schools, as described in a student guide in a introductory student forum context.','Managers blamed a single change because complaints rose quickly.','Because complaints decreased slowly, managers avoided saying that one change alone caused the improvement.','Managers ignored the decline because it was caused by one change.','The decline in complaints was sudden and easy to explain.','B','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_39", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The writer contrasts short-term popularity with long-term reliability for adult learners, as described in a pilot study in a coastal research briefing context.','The writer argues that long-term reliability is impossible.','The writer discusses reliability without mentioning popularity.','The writer points out a difference between being popular now and being dependable over time.','The writer says popularity and reliability are exactly the same.','C','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_39", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'Although school uniforms was initially criticized, later evidence showed that it could be useful when applied carefully in public institutions, as described in a professional workshop in a urban research briefing context.','Later evidence showed that school uniforms should never be applied.','The usefulness of school uniforms was accepted before anyone criticized it.','Early criticism proved that school uniforms had no value at all.','Later evidence suggested that school uniforms, despite early criticism, may have value if used carefully.','D','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_39", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The report does not claim that community gardens solves every problem; it argues only that it can reduce one specific difficulty during periods of change, as described in a policy review in a northern research briefing context.','According to the report, community gardens is not a complete solution but may help with a particular problem.','The report argues that community gardens solves all problems completely.','The report discusses many solutions but never mentions a specific problem.','The report rejects the idea that community gardens can help in any way.','A','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_39", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
