insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',7,'The decline in complaints was gradual, so managers were careful not to attribute it to a single change in public institutions, as described in a pilot study in a advanced reading program context.','Managers blamed a single change because complaints rose quickly.','The decline in complaints was sudden and easy to explain.','Because complaints decreased slowly, managers avoided saying that one change alone caused the improvement.','Managers ignored the decline because it was caused by one change.','C','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_40", "restatement", "practice_pool"]'::jsonb,70,'C1','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',7,'The writer contrasts short-term popularity with long-term reliability during periods of change, as described in a professional workshop in a introductory reading program context.','The writer says popularity and reliability are exactly the same.','The writer argues that long-term reliability is impossible.','The writer discusses reliability without mentioning popularity.','The writer points out a difference between being popular now and being dependable over time.','D','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_40", "restatement", "practice_pool"]'::jsonb,70,'C1','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The report does not claim that traffic cameras solves every problem; it argues only that it can reduce one specific difficulty for adult learners, as described in a research summary.','According to the report, traffic cameras is not a complete solution but may help with a particular problem.','The report argues that traffic cameras solves all problems completely.','The report rejects the idea that traffic cameras can help in any way.','The report discusses many solutions but never mentions a specific problem.','A','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_41", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'Researchers postponed their recommendation because the available data were too limited to support a firm conclusion in public institutions, as described in a public debate in a urban community college context.','The available data forced the researchers to reject all conclusions.','The researchers delayed giving advice since the evidence was insufficient for a definite conclusion.','The researchers made a recommendation because the data were complete.','The researchers postponed collecting data after reaching a firm conclusion.','B','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_41", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The author suggests that frequent practice is effective only when learners receive feedback on their mistakes during periods of change, as described in a training program in a northern community college context.','The author claims feedback is useful only when students stop practicing.','The author believes mistakes should be ignored during practice.','The author believes practice works best if learners are told what they did wrong.','The author suggests that practice and feedback are unrelated.','C','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_41", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',7,'The new system was adopted not because it was cheaper, but because it made the process more transparent in small communities, as described in an evaluation report in a southern community college context.','The process became less transparent after the new system was adopted.','The new system was adopted mainly because it reduced costs.','The new system was rejected because it was not transparent.','The main reason for adopting the new system was improved transparency rather than lower cost.','D','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_41", "restatement", "practice_pool"]'::jsonb,70,'C1','approved',false);
